@Test
void cancellingAConfirmedReservationNotifiesDepartments() {
    Reservation standardPlan = service.create(stay(102, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD));
    Reservation nonRefundablePlan =
            service.create(stay(201, "2027-03-15", "2027-03-16", 1, RatePlan.NON_REFUNDABLE));
    service.confirm(standardPlan.id());
    service.confirm(nonRefundablePlan.id());

    service.cancel(standardPlan.id());
    service.cancel(nonRefundablePlan.id());

    List<Message> sent = sentMessages.all();
    // 2 confirmations × 3 emails (guest, housekeeping, finance)
    // + 1 cancellation with refund × 3 emails (housekeeping, finance with refund, no guest email)
    // + 1 cancellation without refund × 2 emails (housekeeping only, no finance since refund is zero)
    assertEquals(10, sent.size());
    // check housekeeping got notified about both cancellations
    assertTrue(
            sent.stream().anyMatch(m -> m.to().equals("governanca@pousadamarealta.com.br")
                    && m.subject().equals("Reserva cancelada - quarto 102")));
    assertTrue(
            sent.stream().anyMatch(m -> m.to().equals("governanca@pousadamarealta.com.br")
                    && m.subject().equals("Reserva cancelada - quarto 201")));
    // check finance got notified about standard plan refund but not non-refundable
    assertTrue(sent.stream()
            .anyMatch(m -> m.to().equals("financeiro@pousadamarealta.com.br")
                    && m.subject().equals("Reembolso - reserva " + standardPlan.id())
                    && m.body().contains("R$ 499,80")));
    assertTrue(sent.stream().noneMatch(m -> m.to().equals("financeiro@pousadamarealta.com.br")
            && m.subject().equals("Reembolso - reserva " + nonRefundablePlan.id())));
}

